import { useState } from "react";
import CoursePage from "./pages/CoursePage";
import AssessmentPage from "./pages/AssessmentPage";
import VideoPage from "./pages/VideoPage";
import { generateAssessment, checkAssessment, checkSimilarity } from "./api";

function App() {
  // Existing app stages (kept for backward-compat, not used in Dashboard/TeachFlow path)
  const [stage, setStage] = useState("course"); // "course" | "assessment" | "video"
  const [course, setCourse] = useState(null);
  const [questions, setQuestions] = useState(null);

  // App routing between Dashboard and TeachFlow
  const [showTeachFlow, setShowTeachFlow] = useState(false); // default to dashboard

  if (showTeachFlow) {
    return <TeachFlow onExit={() => setShowTeachFlow(false)} />;
  }

  // Dashboard UI is the default
  return <Dashboard onStartTeaching={() => setShowTeachFlow(true)} />;
}

// -----------------------------
// Dashboard UI
// -----------------------------
function Dashboard({ onStartTeaching }) {
  const sampleCourses = [
    {
      id: 1,
      level: "Intermediate",
      badgeColor: "#FDE68A",
      title: "Database Management Systems",
      desc: "Comprehensive guide to DBMS concepts, SQL, and database design principles.",
      author: "Sarah Johnson",
      rating: 4.8,
      learners: 234,
      duration: "2h 30m",
      points: 85,
      tags: ["Database", "SQL"],
      image: "https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=600&q=80&auto=format&fit=crop",
    },
    {
      id: 2,
      level: "Advanced",
      badgeColor: "#FCA5A5",
      title: "React Frontend Development",
      desc: "Master React components, hooks, and modern frontend development.",
      author: "Mike Chen",
      rating: 4.9,
      learners: 567,
      duration: "3h 15m",
      points: 120,
      tags: ["React", "JavaScript"],
      image: "https://images.unsplash.com/photo-1581276879432-15a67f1a7b7b?w=600&q=80&auto=format&fit=crop",
    },
    {
      id: 3,
      level: "Beginner",
      badgeColor: "#A7F3D0",
      title: "Python Data Analysis",
      desc: "Learn data analysis with Python, pandas, and visualization libraries.",
      author: "Emily Rodriguez",
      rating: 4.7,
      learners: 189,
      duration: "4h 20m",
      points: 95,
      tags: ["Python", "Data Science"],
      image: "https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=600&q=80&auto=format&fit=crop",
    },
  ];

  return (
    <div className="dash">
      {/* Top bar */}
      <header className="dash__topbar">
        <div className="dash__brand">
          <span className="dash__logo">📘</span>
          <span className="dash__title">Trade Talk Platform</span>
        </div>
        <div className="dash__right">
          <span className="dash__welcome">Welcome back, <b>vishaalanitha</b></span>
          <span className="dash__points">235 Points</span>
          <button className="dash__logout">Logout</button>
        </div>
      </header>

      {/* Hero cards */}
      <section className="dash__hero">
        <div className="dash__card">
          <div className="dash__cardHead">
            <div className="dash__icon">🧑‍🏫</div>
            <div>
              <h3>Teach & Earn</h3>
              <p>Share your knowledge and earn points by teaching courses to the community.</p>
            </div>
          </div>
          <button className="btnPrimary dash__wideBtn" onClick={onStartTeaching}>Start Teaching</button>
        </div>

        <div className="dash__card">
          <div className="dash__cardHead">
            <div className="dash__icon">📚</div>
            <div>
              <h3>Learn & Grow</h3>
              <p>Use your earned points to access premium courses and expand your skills.</p>
            </div>
          </div>
          <button className="btnSecondary dash__wideBtn">Browse Courses</button>
        </div>
      </section>

      {/* Tabs */}
      <section className="dash__tabs">
        <div className="dash__tab dash__tab--active">Public Catalog</div>
        <div className="dash__tab">AI Assistant</div>
        <div style={{ flex: 1 }} />
        <div className="dash__filter">
          <span>All Categories</span>
          <span className="dash__caret">▾</span>
        </div>
      </section>

      {/* Catalog */}
      <section className="dash__catalog">
        <h2>Public Course Catalog</h2>
        <div className="dash__grid">
          {sampleCourses.map((c) => (
            <div key={c.id} className="course">
              <div className="course__media">
                <img src={c.image} alt={c.title} />
                <span className="course__duration">{c.duration}</span>
              </div>
              <div className="course__body">
                <div className="course__level" style={{ background: c.badgeColor }}>{c.level}</div>
                <div className="course__title">{c.title}</div>
                <div className="course__desc">{c.desc}</div>
                <div className="course__meta">
                  <span className="course__author">by {c.author}</span>
                  <span className="course__stats">⭐ {c.rating} · 👥 {c.learners}</span>
                </div>
                <div className="course__tags">
                  {c.tags.map((t, i) => (
                    <span key={i} className="course__tag">{t}</span>
                  ))}
                </div>
              </div>
              <div className="course__footer">
                <div className="course__points">{c.points} pts</div>
                <button className="btnPrimary">Start Learning</button>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

// -----------------------------
// Teach & Earn (Teach a Course)
// -----------------------------
function TeachFlow({ onExit }) {
  const [step, setStep] = useState(1); // 1: Course Info, 2: Knowledge Test, 3: Upload Video, 4: Complete
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [courseName, setCourseName] = useState("");
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [similarityScore, setSimilarityScore] = useState(null);
  const [file, setFile] = useState(null);

  const threshold = 0.7; // similarity threshold for publishing

  const goDashboard = () => onExit?.();

  const handleGenerateAssessment = async () => {
    setError("");
    if (!courseName.trim()) {
      setError("Please enter a course name.");
      return;
    }
    try {
      setLoading(true);
      const res = await generateAssessment(courseName.trim());
      if (res?.questions && Array.isArray(res.questions) && res.questions.length) {
        setQuestions(res.questions);
        setAnswers(new Array(res.questions.length).fill(""));
        setStep(2);
      } else if (res?.error) {
        setError("Assessment generation failed: " + res.error);
      } else {
        setError("Could not generate questions. Please try again.");
      }
    } catch (e) {
      setError("Server error while generating assessment.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitAssessment = async () => {
    setError("");
    if (!questions.length) return;
    if (answers.some((a) => !a)) {
      setError("Please answer all questions.");
      return;
    }
    try {
      setLoading(true);
      const res = await checkAssessment(courseName, answers, questions);
      if (res?.result === "pass") {
        setStep(3);
      } else {
        setError(res?.message || "You must pass the assessment to proceed.");
        // On failure, return to dashboard immediately
        goDashboard();
      }
    } catch (e) {
      setError("Server error while checking assessment.");
    } finally {
      setLoading(false);
    }
  };

  const handleUploadVideo = async () => {
    setError("");
    if (!file) {
      setError("Please select a video file.");
      return;
    }
    try {
      setLoading(true);
      const res = await checkSimilarity(courseName, file);
      const score = typeof res?.similarity_score === "number" ? res.similarity_score : null;
      setSimilarityScore(score);
      if (score !== null && score >= threshold) {
        setStep(4);
      } else {
        setError("Similarity below threshold. Please review your video and try again.");
      }
    } catch (e) {
      setError("Server error while uploading video or computing similarity.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pageWrap">
      <div className="headerWrap">
        <div className="iconBadge">📘</div>
        <h1 style={{ margin: 8 }}>Teach a Course</h1>
        <p style={{ margin: 0, color: "#667085" }}>
          Share your knowledge and earn points by teaching courses to the community.
        </p>
      </div>

      <Stepper current={step} />

      {step === 1 && (
        <div className="card">
          <h2 style={{ marginTop: 0 }}>What course would you like to teach?</h2>
          <label className="label">Course Name</label>
          <input
            className="input"
            placeholder="e.g., Introduction to Database Management Systems"
            value={courseName}
            onChange={(e) => setCourseName(e.target.value)}
          />

          <div className="tipBox">
            <b>What happens next?</b>
            <ul style={{ marginTop: 8 }}>
              <li>AI will generate an assessment to verify your knowledge</li>
              <li>You’ll need to pass this test to proceed</li>
              <li>Upload your teaching video</li>
              <li>Earn points based on course value and engagement</li>
            </ul>
          </div>

          {error && <div className="errorBox">{error}</div>}

          <div className="buttonGroup">
            <button className="btnPrimary" onClick={handleGenerateAssessment} disabled={loading}>
              {loading ? "Generating..." : "Continue to Assessment"}
            </button>
            <button className="btnSecondary" onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="card">
          <h2 style={{ marginTop: 0 }}>Knowledge Test</h2>
          <p style={{ color: "#667085" }}>Answer all questions correctly to proceed.</p>

          <div className="questionList">
            {questions.map((q, idx) => (
              <div key={idx} className="qBox">
                <div style={{ marginBottom: 8 }}>
                  <b>Q{idx + 1}.</b> {q.question}
                </div>
                <div className="radioList">
                  {q.options?.map((opt, oidx) => (
                    <label key={oidx} className="radioRow">
                      <input
                        type="radio"
                        name={`q-${idx}`}
                        value={opt}
                        checked={answers[idx] === opt}
                        disabled={Boolean(answers[idx])}
                        onChange={(e) => {
                          if (answers[idx]) return; // lock choice after first selection
                          const v = e.target.value;
                          setAnswers((prev) => prev.map((p, i) => (i === idx ? v : p)));
                        }}
                      />
                      <span>{opt}</span>
                    </label>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {error && <div className="errorBox">{error}</div>}

          <div className="buttonGroup">
            <button className="btnPrimary" onClick={handleSubmitAssessment} disabled={loading}>
              {loading ? "Checking..." : "Submit Answers"}
            </button>
            <button className="btnSecondary" onClick={() => setStep(1)}>Back</button>
            <button className="btnSecondary" onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="card">
          <h2 style={{ marginTop: 0 }}>Upload Video</h2>
          <p style={{ color: "#667085" }}>
            Upload your course video. We'll compute how well it matches the course topic. A score ≥ {threshold}
            will be accepted and published to the public catalog.
          </p>

          <input
            type="file"
            accept="video/*"
            onChange={(e) => setFile(e.target.files?.[0] || null)}
            className="fileInput"
          />

          {typeof similarityScore === "number" && (
            <div className="infoBox">Similarity Score: {similarityScore.toFixed(2)}</div>
          )}

          {error && <div className="errorBox">{error}</div>}

          <div className="buttonGroup">
            <button className="btnPrimary" onClick={handleUploadVideo} disabled={loading}>
              {loading ? "Checking..." : "Upload & Check"}
            </button>
            <button className="btnSecondary" onClick={() => setStep(2)}>Back</button>
            <button className="btnSecondary" onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 4 && (
        <div className="card">
          <h2 style={{ marginTop: 0 }}>Complete</h2>
          <div className="successBox">
            ✅ Video successfully uploaded to the public catalog!
          </div>
          <div className="infoBox">You earned 120 points for this course. Great job!</div>

          <div className="buttonGroup">
            <button className="btnPrimary" onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}
    </div>
  );
}

// Styles for Stepper in index.css via classes.
function Stepper({ current }) {
  const steps = ["Course Info", "Knowledge Test", "Upload Video", "Complete"];
  return (
    <div className="stepper">
      {steps.map((label, idx) => {
        const n = idx + 1;
        const active = n === current;
        const done = n < current;
        const circleClass = `step__circle ${done ? "done" : active ? "active" : ""}`;
        const textClass = `step__label ${active ? "active" : ""}`;
        return (
          <div key={n} className="step">
            <div className={circleClass}>{n}</div>
            <div className={textClass}>{label}</div>
            {n !== steps.length && <div className="step__divider" />}
          </div>
        );
      })}
    </div>
  );
}

export default App;
